/**
 * API operations stay compact in the document and render their full details in
 * one reusable right-side dialog generated by `doc-page`.
 */

import { describe, expect, it } from 'vitest';
import { mountPlan } from '../helpers.js';

const ENDPOINT = `
  <doc-endpoint
    method="post"
    path="/api/plans/{id}/validate"
    summary="Validate a plan"
    description="Check semantic markup before building."
    auth="bearer"
    headers="Content-Type: application/json; X-Request-Id: string"
    params="id:path:string:required:Plan identifier; strict:query:boolean:optional:Fail on warnings"
    request="{ markup: string }"
    status="200 OK"
    response="{ valid: boolean }"
  ></doc-endpoint>
`;

function drawer(docPage: Element): HTMLDialogElement {
  return docPage.querySelector('[data-part="endpoint-drawer"]') as HTMLDialogElement;
}

function trigger(docPage: Element): HTMLButtonElement {
  return docPage.querySelector('doc-endpoint [data-part="trigger"]') as HTMLButtonElement;
}

describe('doc-endpoint detail drawer', () => {
  it('creates one reusable drawer as document chrome', () => {
    const docPage = mountPlan(`${ENDPOINT}${ENDPOINT}`);
    const drawers = docPage.querySelectorAll('[data-part="endpoint-drawer"]');

    expect(drawers).toHaveLength(1);
    expect((drawers[0] as HTMLElement).dataset.docChrome).toBe('');
  });

  it('opens from the long endpoint button and renders the attribute payload', () => {
    const docPage = mountPlan(ENDPOINT);
    const detail = drawer(docPage);

    trigger(docPage).click();

    expect(detail.open).toBe(true);
    expect(detail.querySelector('[data-part="endpoint-drawer-title"]')?.textContent).toBe(
      'Validate a plan',
    );
    expect(detail.querySelector('[data-part="endpoint-drawer-path"]')?.textContent).toBe(
      '/api/plans/{id}/validate',
    );
    expect(detail.querySelector('[data-part="endpoint-drawer-description"]')?.textContent).toBe(
      'Check semantic markup before building.',
    );
    expect(detail.querySelector('[data-part="endpoint-drawer-example"]')?.textContent).toContain(
      '{ markup: string }',
    );
  });

  it('parses compact parameters and does not duplicate derived path variables', () => {
    const docPage = mountPlan(ENDPOINT);
    trigger(docPage).click();

    const parameters = drawer(docPage).querySelectorAll('[data-part="endpoint-drawer-parameter"]');
    expect(parameters).toHaveLength(2);
    expect(parameters[0]?.textContent).toContain('id');
    expect(parameters[0]?.textContent).toContain('path');
    expect(parameters[1]?.textContent).toContain('strict');
    expect(parameters[1]?.textContent).toContain('optional');
  });

  it('closes and restores focus to the endpoint trigger', async () => {
    const docPage = mountPlan(ENDPOINT);
    const endpointTrigger = trigger(docPage);
    endpointTrigger.click();

    const detail = drawer(docPage);
    const close = detail.querySelector('[data-part="endpoint-drawer-close"]') as HTMLButtonElement;
    const closed = new Promise<void>((resolve) => {
      detail.addEventListener('close', () => resolve(), { once: true });
    });
    close.click();
    await closed;
    await Promise.resolve();

    expect(detail.open).toBe(false);
    expect(document.activeElement).toBe(endpointTrigger);
  });
});
